def solve_recurrence(y1, y2, max_length=10):
    """
    Generates the sequence y_i based on the recurrence:
    y_{i+1} * y_{i-1} = (y_i - 1)^2 + 1
    Checks for integer results.
    Returns the length of the sequence found.
    """
    if y1 <= 0 or y2 <= 0:
        return 0

    sequence = [y1, y2]

    for i in range(2, max_length):
        # Calculate y_{i+1}
        # y_{i+1} * y_{i-1} = (y_i - 1)^2 + 1
        # y_{i+1} = ((y_i - 1)^2 + 1) / y_{i-1}

        y_i = sequence[i-1]
        y_i_minus_1 = sequence[i-2]

        numerator = (y_i - 1)**2 + 1

        if numerator % y_i_minus_1 != 0:
            # y_{i+1} is not an integer
            return len(sequence)

        y_next = numerator // y_i_minus_1

        # Since y_i were positive, y_next should also be positive.
        # (y_i - 1)^2 + 1 >= 1, and y_{i-1} > 0.
        if y_next <= 0:
             return len(sequence)

        sequence.append(y_next)

    return len(sequence)

# Test initial small values (y1, y2)
