def check_n4(X):
    """Checks for existence of positive integer solutions (x1, x2, x3, x4) for n=4."""
    limit = 50 # Search bound for x_i
    for x1 in range(1, limit + 1):
        for x2 in range(1, limit + 1):
            for x3 in range(1, limit + 1):
                # Condition 1 (i=2): (x3 + 1)(x1 + 1) = x2^2 + 1
                LHS1 = (x3 + 1) * (x1 + 1)
                RHS1 = x2**2 + 1

                if LHS1 == RHS1:
                    # Condition 2 (i=3): (x4 + 1)(x2 + 1) = x3^2 + 1
                    RHS2 = x3**2 + 1
                    denominator = x2 + 1

                    if RHS2 % denominator == 0:
                        x4_plus_1 = RHS2 // denominator
                        x4 = x4_plus_1 - 1

                        if x4 >= 1 and x4 <= limit:
                            return (x1, x2, x3, x4)
    return None

# Test for n=4
solution_n4 = check_n4(None)
print(f"Solution found for n=4 (within bounds): {solution_n4}")

