        x5_plus_1 = RHS3 // denominator3
        x5 = x5_plus_1 - 1

        if x5 >= 1 and x5 <= limit_n5:
            print(f"Solution found for n=5 (within bounds): ({x1}, {x2}, {x3}, {x4}, {x5})")
